import { readDisplaySnapshot, writeDisplaySnapshot } from '../app/local-display-cache.js';

// One immutable opening pool per level. Keep this optional decoration off the
// jackpot's readiness path and restore it immediately on subsequent visits.
export function createJackpotPoolStarts({ load, changed }) {
  const pending = new Map(), retryAt = new Map();
  return level => {
    if (!Number.isSafeInteger(level) || level < 1) return null;
    const key = `jackpot-pool-start-v1:${level}`;
    const valid = value => value?.status === 'resolved' && Number(value.level) === level
      && /^\d+$/.test(String(value.initialWei)) && BigInt(value.initialWei) > 0n;
    const saved = readDisplaySnapshot(key)?.value;
    if (valid(saved)) return BigInt(saved.initialWei);
    if (!pending.has(level) && Date.now() >= (retryAt.get(level) ?? 0)) {
      const request = Promise.resolve().then(() => load(level)).then(value => {
        if (valid(value)) { writeDisplaySnapshot(key, value); changed(); }
        else retryAt.set(level, Date.now() + 30_000);
      }).catch(() => { retryAt.set(level, Date.now() + 30_000); })
        .finally(() => pending.delete(level));
      pending.set(level, request);
    }
    return null;
  };
}
